export function counterGroupthinkMechanism(proposals) {
  const diversityScores = proposals.map(proposal => {
    return calculateDiversityScore(proposal);
  });

  const filteredProposals = proposals.filter((proposal, index) => {
    return diversityScores[index] > THRESHOLD;
  });

  return filteredProposals;
}

function calculateDiversityScore(proposal) {
  // Example calculation for diversity score based on novelty and differentiation
  const noveltyScore = proposal.novelty;
  const differentiationScore = proposal.differentiation;
  return (noveltyScore + differentiationScore) / 2;
}

const THRESHOLD = 0.7;